create table public.asset_previews(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.lookup_sessions on delete cascade,asset_id uuid not null references public.attachments,asset_hash text not null,asset_version integer not null,expires_at timestamptz not null default now()+interval '15 minutes',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.asset_previews enable row level security;
revoke all on public.asset_previews from anon,authenticated;
grant all on public.asset_previews to service_role;
create function public.record_preview(p_token text,p_csrf text,p_asset uuid) returns void language plpgsql security definer set search_path='' as $$declare s public.lookup_sessions;a public.attachments;begin
 select * into strict s from public.lookup_sessions where token_digest=p_token and csrf_digest=p_csrf and expires_at>now() and revoked_at is null;
 select * into strict a from public.attachments where id=p_asset and order_id=s.order_id and release_state='released' and classification='public_derivative' and mime in ('image/jpeg','image/png','image/webp','video/mp4');
 insert into public.asset_previews(session_id,asset_id,asset_hash,asset_version) values(s.id,a.id,a.checksum,a.asset_version);end$$;
create function public.grant_after_preview(p_token text,p_csrf text,p_asset uuid,p_scope text,p_hash text,p_version integer) returns void language plpgsql security definer set search_path='' as $$declare s public.lookup_sessions;begin
 select * into strict s from public.lookup_sessions where token_digest=p_token and csrf_digest=p_csrf and expires_at>now() and revoked_at is null;
 perform 1 from public.orders where id=s.order_id for update;
 if p_scope not in ('website_public_gallery','youtube_publication','tiktok_publication') or not exists(select 1 from public.asset_previews where session_id=s.id and asset_id=p_asset and asset_hash=p_hash and asset_version=p_version and expires_at>now()) or not exists(select 1 from public.attachments where id=p_asset and order_id=s.order_id and checksum=p_hash and asset_version=p_version and release_state='released') then raise exception 'preview required';end if;
 perform public.change_consent(s.order_id,p_asset,p_scope,true);end$$;
create function public.photo_permission(p_order uuid,p_granted boolean) returns void language plpgsql security definer set search_path='' as $$declare o public.orders;begin select * into strict o from public.orders where id=p_order for update;if p_granted and o.inputs->>'age_band'<>'18+' then raise exception 'adult required';end if;insert into public.consent_events(order_id,scope,granted,notice_version,age_band) values(p_order,'customer_photo_for_private_video',p_granted,'v1',o.inputs->>'age_band');insert into public.audit_events(action,resource_id,changed_fields) values('photo_permission_changed',p_order,array['customer_photo_for_private_video']);end$$;
create function public.immutable_released_asset() returns trigger language plpgsql set search_path='' as $$begin if old.release_state='released' and (new.checksum,new.asset_version,new.storage_key,new.order_id,new.classification,new.mime) is distinct from (old.checksum,old.asset_version,old.storage_key,old.order_id,old.classification,old.mime) then raise exception 'released asset immutable: create new asset';end if;return new;end$$;
create trigger immutable_asset before update on public.attachments for each row execute function public.immutable_released_asset();
revoke all on function public.record_preview(text,text,uuid),public.grant_after_preview(text,text,uuid,text,text,integer),public.photo_permission(uuid,boolean),public.immutable_released_asset() from public,anon,authenticated;
grant execute on function public.record_preview(text,text,uuid),public.grant_after_preview(text,text,uuid,text,text,integer),public.photo_permission(uuid,boolean),public.immutable_released_asset() to service_role;
